import{_ as a,C as o,c as n,o as i,a3 as s,G as t}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Sources and mediums","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/setup/sources-and-mediums.md","filePath":"master/human-resources/recruitment/setup/sources-and-mediums.md","lastUpdated":1792041590000}'),l={name:"master/human-resources/recruitment/setup/sources-and-mediums.md"};function u(m,e,c,d,g,h){const r=o("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=s('<h1 id="sources-and-mediums" tabindex="-1">Sources and mediums <a class="header-anchor" href="#sources-and-mediums" aria-label="Permalink to &quot;Sources and mediums&quot;">​</a></h1><p>Sources and mediums tell you where an applicant came from. A source is the place, such as LinkedIn or Referral. A medium is the channel used to reach you, such as Email or Phone. Tracking both shows which hiring channels work best.</p><blockquote><p><strong>In simple words:</strong> Source is where the applicant found you. Medium is how they reached you.</p></blockquote><p>Open <code>Recruitments → Configuration → Sources</code> or <code>Recruitments → Configuration → Mediums</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. Both lists come with sample data.</p></div><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>The list has one column, <strong>Name</strong>. Sample sources are <strong>Search engine</strong>, <strong>Lead Recall</strong>, <strong>Newsletter</strong>, <strong>Facebook</strong>, <strong>X</strong>, <strong>LinkedIn</strong>, <strong>Monster</strong>, <strong>Glassdoor</strong>, <strong>Craigslist</strong> and <strong>Referral</strong>.</p>',7)),t(r,{src:"/images1/recruitment/set_sources_list.png",alt:"Sources list with sample sources such as LinkedIn and Referral"}),e[1]||(e[1]=s('<h3 id="create-a-source" tabindex="-1">Create a source <a class="header-anchor" href="#create-a-source" aria-label="Permalink to &quot;Create a source&quot;">​</a></h3><ol><li>Open <code>Recruitments → Configuration → Sources</code>.</li><li>Click <strong>New Source</strong>. A <strong>Create Sources</strong> window opens.</li><li>Type <strong>Job Fair</strong> in <strong>Name</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',2)),t(r,{src:"/images1/recruitment/set_source_create.png",alt:"Create Sources window with the name Job Fair"}),e[2]||(e[2]=s('<ul><li><strong><em>Name:</em></strong> (required) the source label.</li></ul><h2 id="mediums" tabindex="-1">Mediums <a class="header-anchor" href="#mediums" aria-label="Permalink to &quot;Mediums&quot;">​</a></h2><p>Sample mediums are <strong>Phone</strong>, <strong>Direct</strong>, <strong>Email</strong>, <strong>Banner</strong>, <strong>X</strong>, <strong>Facebook</strong>, <strong>LinkedIn</strong>, <strong>Television</strong>, <strong>Google</strong> and <strong>Referral</strong>.</p>',3)),t(r,{src:"/images1/recruitment/set_mediums_list.png",alt:"Mediums list with sample mediums such as Email and Phone"}),e[3]||(e[3]=s('<h3 id="create-a-medium" tabindex="-1">Create a medium <a class="header-anchor" href="#create-a-medium" aria-label="Permalink to &quot;Create a medium&quot;">​</a></h3><ol><li>Open <code>Recruitments → Configuration → Mediums</code>.</li><li>Click <strong>New Medium</strong>. A <strong>Create Mediums</strong> window opens.</li><li>Type <strong>Walk-in</strong> in <strong>Name</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',2)),t(r,{src:"/images1/recruitment/set_medium_create.png",alt:"Create Mediums window with the name Walk-in"}),e[4]||(e[4]=s('<ul><li><strong><em>Name:</em></strong> (required) the medium label.</li></ul><h2 id="where-they-are-used" tabindex="-1">Where they are used <a class="header-anchor" href="#where-they-are-used" aria-label="Permalink to &quot;Where they are used&quot;">​</a></h2><p>The applicant form has a <strong>Source &amp; Medium</strong> section with a <strong>Source</strong> field and a <strong>Medium</strong> field. Pick one value from each. For Rahul Verma, you could choose <strong>Referral</strong> as the source and <strong>Email</strong> as the medium.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Sources and mediums are shared records. Other apps that track campaigns read the same lists.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../applicants/add-applicant.html">Add an applicant</a></li><li><a href="./../applicants/applicant-list.html">Applicant list</a></li><li><a href="./tags-degrees.html">Tags and degrees</a></li><li><a href="./">Setup overview</a></li></ul>',6))])}const S=a(l,[["render",u]]);export{_ as __pageData,S as default};
